// A database client as seen by the test-isolation helpers. `getDb()` in
// src/database/index.ts constructs the concrete libsql client, but these helpers
// only rely on the ability to run SQL and close the connection.
export interface TestDatabaseClient {
  close: () => any;
  execute: (sql: string) => Promise<any>;
}

// The registry must be shared across every module instance so that
// closeTestDatabaseClients() can close clients created by a database module that
// was imported before a module-cache reset. A module-level array would be reset
// alongside the module, so it lives on globalThis behind a unique symbol instead.
const REGISTRY_KEY = Symbol.for('promptfoo.testDatabaseClients');

type GlobalWithRegistry = typeof globalThis & {
  [REGISTRY_KEY]?: Set<TestDatabaseClient>;
};

function getRegistry(): Set<TestDatabaseClient> {
  const globalWithRegistry = globalThis as GlobalWithRegistry;
  if (!globalWithRegistry[REGISTRY_KEY]) {
    globalWithRegistry[REGISTRY_KEY] = new Set<TestDatabaseClient>();
  }
  return globalWithRegistry[REGISTRY_KEY];
}

/**
 * Registers a database client in the global test registry so that
 * {@link closeTestDatabaseClients} is aware of it and can close it later.
 *
 * Called from getDb() in src/database/index.ts when IS_TESTING is set, so that
 * module-level isolation works even after the database module is reloaded.
 */
export function registerTestDatabaseClient(client: TestDatabaseClient): void {
  getRegistry().add(client);
}

/**
 * Escapes a SQL identifier by wrapping it in double-quotes and doubling any
 * embedded double-quote characters, e.g. `table"name` becomes `"table""name"`.
 */
function escapeIdentifier(name: string): string {
  return `"${name.replace(/"/g, '""')}"`;
}

const DROP_KEYWORDS: Record<string, string> = {
  table: 'TABLE',
  view: 'VIEW',
  trigger: 'TRIGGER',
};

/**
 * Resets the schema of a given database client by dropping all user-created
 * tables, views, and triggers (but NOT indexes, which are dropped implicitly
 * alongside their tables). The final statement executed is always
 * `PRAGMA foreign_keys = ON`, even if dropping an object fails.
 */
export async function resetTestDatabaseClient(client: {
  close: () => any;
  execute: (sql: string) => Promise<{ rows: Array<{ type: string; name: string }> }>;
}): Promise<void> {
  try {
    const result = await client.execute(
      "SELECT type, name FROM sqlite_master WHERE type IN ('table', 'view', 'trigger', 'index') AND name NOT LIKE 'sqlite_%'",
