    for (const { type, name } of result.rows) {
      const keyword = DROP_KEYWORDS[type];
      // Indexes (and any unexpected object types) are intentionally skipped;
      // they are removed automatically when their owning table is dropped.
      if (!keyword) {
        continue;
      }
      try {
        await client.execute(`DROP ${keyword} IF EXISTS ${escapeIdentifier(name)}`);
      } catch (err) {
        logger.warn(`Failed to drop ${type} "${name}" while resetting test database: ${err}`);
      }
    }
  } finally {
    // Restore the default foreign-key enforcement. This must be the last
    // statement executed regardless of any errors above.
    await client.execute('PRAGMA foreign_keys = ON');
  }
}

/**
